fn parse_int(s: Str) -> Int {
    let mut n = 0
    for c in s.chars() {
        if c.is_digit(10) {
            n = n * 10 + c.to_digit(10).unwrap()
        } else {
            return None
        }
    }
    return Some(n)
}

fn int_to_str(n: Int) -> Str {
    let mut s = String.new()
    let mut nn = n
    while nn > 0 {
        let digit = nn % 10
        s.insert(0, char(digit + 48))
        nn = nn / 10
    }
    return s
}

